    # Align the repeated patterns by their foreground overlap.
    choices = []
    for d in range(-3,4):
        B = {(k,x+d) for row in B0 for k,x in row}
        union = sum(len(row) for row in A) + sum(len(row) for row in B0) - len(set().union(*A) & B)
        inter = len(set().union(*A) & B)
